CREATE TABLE source(v INT,s VARCHAR);
INSERT INTO source VALUES(1,'{}'),(2,NULL),(3,'[]');
SELECT v,s FORMAT JSON AS j,s IS JSON WITH UNIQUE KEYS AS valid,JSON_OBJECT('n':v,'j':s FORMAT JSON ABSENT ON NULL) AS obj FROM source ORDER BY v;
SELECT JSON_ARRAY(SELECT v FROM source ORDER BY v DESC) AS a;
CREATE TABLE saved(j JSON DEFAULT JSON_ARRAY(SELECT v FROM source ORDER BY v DESC));
INSERT INTO saved DEFAULT VALUES;
