TABLE saved;
CREATE TABLE collected AS SELECT JSON_OBJECT('n':v,'j':s FORMAT JSON) AS j FROM source;
SELECT MIN(j) AS lo,MAX(j) AS hi FROM collected;
SELECT ARRAY_AGG(j ORDER BY j) AS a FROM collected;
DROP TABLE source;
DROP TABLE saved,collected,source;
